from solution import specialFilter
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


ODD = {'1', '3', '5', '7', '9'}

def ref_count(nums):
    """Obviously-correct reference for integers: >10 and first/last decimal digits odd."""
    c = 0
    for n in nums:
        # only define for ints (bool excluded via type check to avoid confusion)
        if isinstance(n, bool):
            continue
        if isinstance(n, int) and n > 10:
            s = str(n)
            if s[0] in ODD and s[-1] in ODD:
                c += 1
    return c


# ---- concrete spec examples ----

def test_spec_example_1():
    assert specialFilter([15, -73, 14, -15]) == 1

def test_spec_example_2():
    assert specialFilter([33, -2, -3, 45, 21, 109]) == 2


# ---- boundaries named in spec: >10, odd digits ----

def test_empty_list_returns_zero():
    assert specialFilter([]) == 0

def test_boundary_ten_excluded_eleven_included():
    # 10 is not >10 so excluded even though last digit even anyway;
    # 11 is >10 with first=1 last=1 both odd so included.
    assert specialFilter([10]) == 0
    assert specialFilter([11]) == 1
    assert specialFilter([10, 11]) == 1

def test_threshold_strictly_greater_than_ten():
    # 9,10 never count; 11..19 with odd last digit count iff first digit odd
    assert specialFilter([9, 10, 12, 14, 20]) == 0
    assert specialFilter([11, 13, 15, 17, 19]) == 5

def test_first_digit_even_excluded():
    # first digit 2,4,6,8 -> excluded even if last digit odd
    assert specialFilter([21, 45, 67, 89, 200, 400]) == 0

def test_last_digit_even_excluded():
    # first digit odd but last digit even -> excluded
    assert specialFilter([12, 14, 16, 18, 10, 30, 50, 110, 132]) == 0

def test_negative_numbers_never_count():
    # negatives are never >10
    assert specialFilter([-15, -73, -33, -11, -111, -13579]) == 0

def test_single_qualifying_and_non_qualifying():
    assert specialFilter([15]) == 1
    assert specialFilter([33]) == 1
    assert specialFilter([109]) == 1
    assert specialFilter([14]) == 0
    assert specialFilter([22]) == 0


# ---- properties / metamorphic ----

@given(st.lists(st.integers(min_value=-2000, max_value=2000), max_size=30))
def test_reference_model_equivalence_ints(nums):
    assert specialFilter(nums) == ref_count(nums)

@given(st.lists(st.integers(min_value=-5000, max_value=5000), max_size=30))
def test_count_between_zero_and_length(nums):
    r = specialFilter(nums)
    assert isinstance(r, int)
    assert 0 <= r <= len(nums)

@given(st.lists(st.integers(min_value=-1000, max_value=1000), max_size=20))
def test_permutation_invariance(nums):
    # counting does not depend on order
    import random
    shuffled = list(nums)
    # deterministic shuffle derived from data: reverse + rotate
    shuffled = shuffled[::-1]
    assert specialFilter(nums) == specialFilter(shuffled)
    assert specialFilter(nums) == specialFilter(sorted(nums))

@given(st.lists(st.integers(min_value=-1000, max_value=1000), max_size=20))
def test_additivity_over_concatenation(nums):
    assume(len(nums) >= 2)
    mid = len(nums) // 2
    a, b = nums[:mid], nums[mid:]
    assert specialFilter(a + b) == specialFilter(a) + specialFilter(b)

@given(st.lists(st.integers(min_value=-1000, max_value=1000), max_size=20), st.integers(min_value=-1000, max_value=1000))
def test_adding_element_increments_by_at_most_one(nums, x):
    before = specialFilter(nums)
    after = specialFilter(nums + [x])
    assert after in (before, before + 1)
    # increment iff x itself qualifies
    assert (after == before + 1) == (ref_count([x]) == 1)

@given(st.integers(min_value=11, max_value=5000))
def test_last_digit_parity_determines_count_for_odd_first_digit(n):
    # For numbers with odd first digit, count == (last digit odd)
    s = str(n)
    if s[0] in ODD:
        expected = 1 if s[-1] in ODD else 0
        assert specialFilter([n]) == expected

@given(st.integers(min_value=11, max_value=5000))
def test_first_digit_parity_determines_count_for_odd_last_digit(n):
    s = str(n)
    if s[-1] in ODD:
        expected = 1 if s[0] in ODD else 0
        assert specialFilter([n]) == expected

def test_large_numbers_first_last_odd():
    # 1...9, 3...3, 9...9 with many digits
    assert specialFilter([1999999992]) == 0  # ends even
    assert specialFilter([1999999991]) == 1
    assert specialFilter([3999999993]) == 1
    assert specialFilter([9999999999]) == 1
    assert specialFilter([2999999999]) == 0  # starts even

def test_duplicates_count_each_occurrence():
    assert specialFilter([15, 15, 15]) == 3
    assert specialFilter([14, 14, 14]) == 0
    assert specialFilter([33] * 5) == 5
